package com.example.interp;

import com.badlogic.gdx.ApplicationAdapter;
import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.backends.headless.HeadlessApplication;
import com.badlogic.gdx.backends.headless.HeadlessApplicationConfiguration;
import com.badlogic.gdx.files.FileHandle;
import com.badlogic.gdx.math.Interpolation;

import java.io.FileOutputStream;
import java.io.IOException;
import java.io.OutputStreamWriter;
import java.io.Reader;
import java.io.Writer;
import java.lang.reflect.Field;
import java.nio.charset.StandardCharsets;
import java.util.Locale;
import java.util.Properties;

public class Main {

    public static void main(String[] args) throws Exception {
        if (args.length != 2) {
            System.err.println("Usage: <config-path> <output-path>");
            System.exit(1);
        }
        String configPath = args[0];
        String outputPath = args[1];

        HeadlessApplicationConfiguration config = new HeadlessApplicationConfiguration();
        config.updatesPerSecond = 0;

        InterpListener listener = new InterpListener(configPath, outputPath);
        HeadlessApplication app = new HeadlessApplication(listener, config);

        // Join the main loop thread so the JVM exits cleanly.
        Field f = HeadlessApplication.class.getDeclaredField("mainLoopThread");
        f.setAccessible(true);
        Thread t = (Thread) f.get(app);
        t.join();

        if (listener.failed) {
            System.exit(1);
        }
    }

    static class InterpListener extends ApplicationAdapter {
        private final String configPath;
        private final String outputPath;

        private Interpolation interp;
        private float start;
        private float end;
        private int samples;
        private String curveName;

        private int currentSample = 0;
        private boolean initialized = false;
        boolean failed = false;

        private final StringBuilder sb = new StringBuilder();

        InterpListener(String configPath, String outputPath) {
            this.configPath = configPath;
            this.outputPath = outputPath;
        }

        @Override
        public void create() {
            try {
                FileHandle fh = Gdx.files.absolute(configPath);
                Properties p = new Properties();
                try (Reader r = fh.reader("UTF-8")) {
                    p.load(r);
                }

                curveName = p.getProperty("curve");
                if (curveName == null) {
                    throw new IllegalArgumentException("Missing 'curve' property");
                }

                Field curveField;
                try {
                    curveField = Interpolation.class.getField(curveName);
                } catch (NoSuchFieldException e) {
                    throw new IllegalArgumentException("Unknown curve: " + curveName);
                }
                Object val = curveField.get(null);
                if (!(val instanceof Interpolation)) {
                    throw new IllegalArgumentException("Field is not an Interpolation: " + curveName);
                }
                interp = (Interpolation) val;

                String startStr = p.getProperty("start");
                String endStr = p.getProperty("end");
                String samplesStr = p.getProperty("samples");
                if (startStr == null || endStr == null || samplesStr == null) {
                    throw new IllegalArgumentException("Missing required property");
                }
                start = Float.parseFloat(startStr);
                end = Float.parseFloat(endStr);
                samples = Integer.parseInt(samplesStr);
                if (samples < 2) {
                    throw new IllegalArgumentException("samples must be >= 2");
                }

                initialized = true;
            } catch (Exception e) {
                System.err.println("Error: " + e.getMessage());
                failed = true;
                Gdx.app.exit();
            }
        }

        @Override
        public void render() {
            if (!initialized || failed) {
                Gdx.app.exit();
                return;
            }
            if (currentSample >= samples) {
                Gdx.app.exit();
                return;
            }

            int i = currentSample;
            float t;
            if (i == samples - 1) {
                t = 1.0f;
            } else {
                t = i / (float) (samples - 1);
            }

            float v = interp.apply(start, end, t);

            if (currentSample == 0) {
                sb.append("curve=").append(curveName).append('\n');
                sb.append("samples=").append(samples).append('\n');
            }
            sb.append(String.format(Locale.ROOT, "%.6f", v)).append('\n');

            currentSample++;
            if (currentSample >= samples) {
                Gdx.app.exit();
            }
        }

        @Override
        public void dispose() {
            if (failed || sb.length() == 0) {
                return;
            }
            try (Writer w = new OutputStreamWriter(
                    new FileOutputStream(outputPath), StandardCharsets.UTF_8)) {
                w.write(sb.toString());
            } catch (IOException e) {
                System.err.println("Failed to write output: " + e.getMessage());
                failed = true;
            }
        }
    }
}
